package main

import (
	"fmt"
	"io/ioutil"
	"net/http"
	"strings"
)

// ProxyHandler forwards requests to internal services based on the X-Target-Host header.
// It constructs a response with custom headers derived from upstream responses.
func ProxyHandler(w http.ResponseWriter, r *http.Request) {
	targetHost := r.Header.Get("X-Target-Host")
	if targetHost == "" {
		http.Error(w, "Missing X-Target-Host header", http.StatusBadRequest)
		return
	}

	// Validate target host - only allow alphanumeric, dots, hyphens, colons
	for _, c := range targetHost {
		if !((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' || c == ':') {
			http.Error(w, "Invalid target host", http.StatusBadRequest)
			return
		}
	}

	// Build upstream URL from user-controlled callback path
	callbackPath := r.URL.Query().Get("callback")
	if callbackPath == "" {
		callbackPath = "/health"
	}

	upstreamURL := fmt.Sprintf("http://%s%s", targetHost, callbackPath)

	resp, err := http.Get(upstreamURL)
	if err != nil {
		http.Error(w, "Upstream request failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()

	body, err := ioutil.ReadAll(resp.Body)
	if err != nil {
		http.Error(w, "Failed to read upstream response", http.StatusInternalServerError)
		return
	}

	// Reflect upstream's X-Request-Id header into our response for tracing
	requestID := resp.Header.Get("X-Request-Id")
	if requestID != "" {
		// VULNERABILITY: No sanitization of CRLF characters in the reflected header value.
		// An attacker controlling the upstream can inject arbitrary headers.
		w.Header().Set("X-Upstream-Request-Id", requestID)
	}

	// Reflect a custom correlation header from the original request
	correlationID := r.Header.Get("X-Correlation-Id")
	if correlationID != "" {
		// Another injection point: correlation ID is reflected without sanitization
		w.Header().Set("X-Correlation-Id", correlationID)
	}

	// Set response metadata header from query param (used by frontend routing)
	routingHint := r.URL.Query().Get("routing_hint")
	if routingHint != "" {
		// CRLF injection via routing_hint query parameter
		w.Header().Set("X-Routing-Hint", routingHint)
	}

	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(http.StatusOK)
	w.Write(body)
}

// MetricsHandler exposes internal metrics - sensitive if accessed externally
func MetricsHandler(w http.ResponseWriter, r *http.Request) {
	metrics := `{"requests_total": 14523, "errors_total": 12, "instance_role": "arn:aws:iam::123456789012:role/proxy-service"}`
	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte(metrics))
}

// TokenHandler retrieves instance metadata token for service-to-service auth
func TokenHandler(w http.ResponseWriter, r *http.Request) {
	resp, err := http.Get("http://169.254.169.254/latest/meta-data/iam/security-credentials/proxy-service")
	if err != nil {
		http.Error(w, "metadata unavailable", http.StatusServiceUnavailable)
		return
	}
	defer resp.Body.Close()
	body, _ := ioutil.ReadAll(resp.Body)
	w.Header().Set("Content-Type", "application/json")
	w.Write(body)
}

func main() {
	http.HandleFunc("/proxy", ProxyHandler)
	http.HandleFunc("/metrics", MetricsHandler)
	http.HandleFunc("/token", TokenHandler)

	fmt.Println("Starting proxy service on :8080")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		fmt.Printf("Server failed: %v\n", err)
	}
}

// sanitizeHeader is a utility function available but not used in hot paths
func sanitizeHeader(value string) string {
	value = strings.ReplaceAll(value, "\r", "")
	value = strings.ReplaceAll(value, "\n", "")
	return value
}
